input.command:
cd /tmp && cat > /tmp/t.js <<'EOF'
const http=require('http');const axios=require('/testbed');
const s=http.createServer((q,r)=>{let n=0;q.on('data',c=>n+=c.length);q.on('end',()=>r.end(String(n)))}).listen(0,async()=>{
 const u='http://localhost:'+s.address().port;
 try{console.log((await axios.post(u,'x'.repeat(2e7))).data)}catch(e){console.log('ERR',e.message)}
 try{await axios.post(u,'x'.repeat(2e7),{maxBodyLength:1000})}catch(e){console.log('ERR',e.message)}
 s.close();});
EOF
timeout 60 node /tmp/t.js

